weight = float(input())
height_cm = float(input())
if weight <= 0 or height_cm <= 0:
    print("Invalid input")
else:
    height_m = height_cm / 100
    bmi = weight / height_m ** 2
    if bmi < 18.5:
        category = "Underweight"
    elif bmi < 24:
        category = "Normal"
    elif bmi < 27:
        category = "Overweight"
    else:
        category = "Obese"
    print(f"BMI:{bmi:.2f}")
    print(category)

