n, m = map(int, input().split())
if n > 0 and m > 0:
    for i in range(1, n + 1):
        first = (i - 1) * m + 1
        last = i * m
        if i % 2 != 0:
            for value in range(first, last + 1):
                print(f"{value:4d}", end="")
        else:
            for value in range(last, first - 1, -1):
                print(f"{value:4d}", end="")
        print()

line = input()
