if not scores:
    print("No data")
else:
    average = sum(scores) / len(scores)
    print(
        f"count={len(scores)} max={max(scores)} "
        f"min={min(scores)} avg={average:.1f}"
    )

scores = [int(value) for value in input().split()]
distinct = sorted(set(scores))
if len(distinct) < 2:
    print("No second distinct score")
else:
    print(distinct[-2])

scores = [int(value) for value in input().split()]
highest = None
second = None
for score in scores:
    if highest is None or score > highest:
        second = highest
        highest = score
    elif score != highest and (second is None or score > second):
        second = score
if second is None:
    print("No second distinct score")
else:
    print(second)
